add(r'''<script>
const A=JSON.parse(document.getElementById('data').textContent),K=['manual_primitive_s','vla_primitive_s','tool_other_s','sdk_non_mcp_s','outside_sdk_s'];const f=n=>Number(n).toLocaleString('en-US',{minimumFractionDigits:1,maximumFractionDigits:1});const e=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');const sn=s=>({'libero_spatial_task':'Task','libero_spatial_swap':'Swap','libero_10_swap':'Long'})[s];let shown=[];
function tab(h,r){return '<div class="scroll"><table><thead><tr>'+h.map(x=>'<th>'+e(x)+'</th>').join('')+'</tr></thead><tbody>'+r.map(a=>'<tr>'+a.map(x=>'<td>'+e(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function draw(){let m=document.getElementById('model').value,s=document.getElementById('suite').value,o=document.getElementById('outcome').value,q=document.getElementById('search').value.toLowerCase();shown=A.filter(x=>(!m||x.model===m)&&(!s||x.suite===s)&&(!o||String(x.environment_success)===o)&&(!q||('t'+x.task+' '+x.task_language).toLowerCase().includes(q)));document.getElementById('count').textContent=shown.length+' / 120 集';document.querySelector('#allrows tbody').innerHTML=shown.map(x=>'<tr><td>'+e(x.model.replace('gpt-6-','')+' / '+sn(x.suite))+'</td><td>t'+x.task+' / '+x.seed+'</td><td><span class="badge '+(!x.environment_success?'fail':'')+'">'+(x.environment_success?'成功':'失败')+'</span></td><td>'+f(x.elapsed_s)+'</td>'+K.map(k=>'<td>'+f(x[k])+'</td>').join('')+'<td>'+f(x.load_s)+'</td><td>'+x.request_count+'</td><td><button data-row="'+A.indexOf(x)+'">查看</button></td></tr>').join('')}
function detail(i){const x=A[i];document.getElementById('detail').innerHTML='<h3>'+e(x.model+' / '+x.suite+' / t'+x.task+' / seed'+x.seed)+'</h3><p>'+e(x.task_language)+'</p><p>选中 '+e(x.attempt)+'；环境成功='+x.environment_success+'。prefill / 完整 thinking / 纯 π 前向 / 纯仿真：<b>未单独测量</b>。</p>'+tab(['指标','值'],[['episode',f(x.elapsed_s)+' s'],['SDK',f(x.sdk_s)+' s'],['MCP 区间并集',f(x.tool_union_s)+' s'],['可见 reasoning 事件并集（不是完整 thinking）',f(x.reasoning_visible_union_s)+' s'],['VLA 模型加载日志段（episode 之外）',f(x.load_s)+' s'],['计量响应 / 文本消息 / MCP 工具',x.request_count+' / '+x.agent_message_count+' / '+x.tool_count],['动作原语 / π chunks',x.action_count+' / '+x.vla_chunks],['累计输入 / 缓存输入',x.input_tokens.toLocaleString()+' / '+x.cached_input_tokens.toLocaleString()],['输出 / reasoning Token',x.output_tokens.toLocaleString()+' / '+x.reasoning_tokens.toLocaleString()],['录像帧数（不转换为墙钟）',x.video_frames]])+'<details><summary>各工具调用数及 duration 累计（非并集，勿再加到总时长）</summary>'+tab(['工具','次数','累计秒'],Object.entries(x.tool_counts).map(([k,v])=>[k,v,f(x.tool_times_s[k])]))+'</details><details><summary>每个计量响应的 Token 输入输出</summary>'+tab(['序号','input','cached','output','reasoning'],x.request_usage.map((u,j)=>[j+1,u.input_tokens,u.cached_input_tokens,u.output_tokens,u.reasoning_output_tokens]))+'</details><details><summary>证据哈希与初始消息长度</summary><pre>'+e(JSON.stringify({transcript:x.transcript_sha256,states:x.state_sha256,stream:x.stream_sha256,prompt:x.prompt_sha256,base:x.base_hash,initial_messages:x.initial_messages},null,2))+'</pre></details>';document.getElementById('detail').scrollIntoView({behavior:'smooth'})}
['model','suite','outcome'].forEach(id=>document.getElementById(id).addEventListener('change',draw));document.getElementById('search').addEventListener('input',draw);document.querySelector('#allrows').addEventListener('click',v=>{if(v.target.dataset.row!==undefined)detail(Number(v.target.dataset.row))});document.getElementById('download').onclick=()=>{let keys=['model','suite','task','seed','attempt','environment_success','elapsed_s',...K,'load_s','request_count','action_count','vla_chunks','input_tokens','cached_input_tokens','reasoning_tokens'];let csv='﻿'+[keys.join(','),...shown.map(x=>keys.map(k=>'"'+String(x[k]).replaceAll('"','""')+'"').join(','))].join(String.fromCharCode(13,10));let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download='rpent-runtime-filtered.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
function chart(t){let x=A.find(x=>x.model==='gpt-6-astra'&&x.suite==='libero_10_swap'&&x.task===t&&x.seed===1),u=x.request_usage,w=500,h=240,points=k=>u.map((a,i)=>`${45+i/(u.length-1)*435},${195-a[k]/160000*165}`).join(' ');document.getElementById('context'+t).innerHTML='<svg class="contextsvg" viewBox="0 0 500 240" role="img" aria-label="每次请求输入及缓存 Token"><text x="10" y="18" font-size="12" fill="#536c65">160k tokens</text><path d="M45 25 V195 H480" stroke="#a9bbb2" fill="none"/><polyline points="'+points('input_tokens')+'" fill="none" stroke="#1c7b86" stroke-width="2.5"/><polyline points="'+points('cached_input_tokens')+'" fill="none" stroke="#cc9454" stroke-width="2" stroke-dasharray="4 3"/><text x="45" y="219" font-size="12">1</text><text x="425" y="219" font-size="12">响应 '+u.length+'</text><text x="12" y="197" font-size="12">0</text></svg>'}
document.getElementById('trajectories').innerHTML=A.filter(x=>x.trajectory).map(x=>'<details><summary>'+e(x.model+' / t'+x.task+' / seed'+x.seed)+'</summary>'+tab(['动作','调用','原语 s','结果（关键字段）'],x.trajectory.filter(z=>z.command).map(z=>[z.step_idx,z.command.action+(z.command.prompt?' · '+z.command.prompt:''),f(z.elapsed_s),JSON.stringify(Object.fromEntries(Object.entries(z.result).filter(([k,v])=>['success','chunks_used','steps_used','final_dist_m','peak_lift_m','final_gripper_opening','terminated'].includes(k))))]))+'</details>').join('');draw();chart(0);chart(9);
</script></html>''')
